    @Query("SELECT * FROM tasks")
    fun getAllTasks(): LiveData<List<TaskEntity>>

    @Insert
    suspend fun insert(task: TaskEntity)
}

class TaskRepository(private val taskDao: TaskDao) {
    fun getAllTasks(): LiveData<List<TaskEntity>> = taskDao.getAllTasks()

    suspend fun insert(task: TaskEntity) = taskDao.insert(task)
}

class TaskViewModel(private val repository: TaskRepository) : ViewModel() {
    val allTasks: LiveData<List<TaskEntity>> = repository.getAllTasks()

    fun addTask(text: String) {
        if (text.isBlank()) return
        viewModelScope.launch {
            repository.insert(TaskEntity(text = text))
        }
    }
}
